package com.geometrydash.deluxe;
import android.app.Activity;import android.os.Bundle;import android.content.pm.ActivityInfo;import android.content.SharedPreferences;import android.graphics.*;import android.media.*;import android.view.*;import java.util.*;
public class MainActivity extends Activity{
 Game game; public void onCreate(Bundle b){super.onCreate(b);setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);game=new Game();setContentView(game);}protected void onPause(){if(game!=null)game.stopMusic();super.onPause();}protected void onResume(){super.onResume();if(game!=null&&game.page==4&&game.started)game.music();}
 class Game extends View{
 Paint p=new Paint(3);Random rng=new Random(42);SharedPreferences prefs;int page=0,level=0,mode=0,skin=0,tool=1,best,wins,score;int[] colors={0xff24e6ff,0xffff4f9a,0xffffd34f,0xffa5ff54,0xffbd85ff,0xfff6fbff,0xffff774c,0xff57ffd0};String[] levels={"STEREO MADNESS","BACK ON TRACK","POLARGEIST","DRY OUT"};int[] skies={0xff101d3b,0xff261536,0xff102b38,0xff311b36};ArrayList<Hit> ui=new ArrayList<>();ArrayList<Obstacle> obs=new ArrayList<>();ArrayList<Particle> particles=new ArrayList<>();ArrayList<Integer> custom=new ArrayList<>();float W,H,floor,px=150,py,vy,world,last,dt,trail;boolean started,dead,won,holding,own,muted;AudioTrack music;
 Game(){super(MainActivity.this);prefs=getSharedPreferences("deluxe",0);best=prefs.getInt("best",0);wins=prefs.getInt("wins",0);skin=prefs.getInt("skin",0);String s=prefs.getString("map","");for(String v:s.split(","))try{custom.add(Integer.parseInt(v));}catch(Exception e){}}
 void music(){if(muted||music!=null)return;try{int sr=22050,n=sr*4;short[] a=new short[n];int[] notes={659,659,784,880,784,659,587,523,587,659,523,440,523,587,659,784};for(int i=0;i<n;i++){double t=i/(double)sr,b=(t*4)%1;int hz=notes[(int)(t*4)%notes.length];a[i]=(short)(Math.sin(2*Math.PI*hz*t)*2300*Math.min(1,Math.min(b*10,(1-b)*10)));}music=new AudioTrack(AudioManager.STREAM_MUSIC,sr,AudioFormat.CHANNEL_OUT_MONO,AudioFormat.ENCODING_PCM_16BIT,n*2,AudioTrack.MODE_STATIC);music.write(a,0,n);music.setLoopPoints(0,n,-1);music.setVolume(.24f);music.play();}catch(Exception e){stopMusic();}}
 void stopMusic(){if(music!=null){try{music.stop();}catch(Exception e){}music.release();music=null;}}
 void text(Canvas c,String s,float x,float y,int z,int col){p.setTypeface(Typeface.create("sans-serif",1));p.setTextSize(z);p.setColor(col);c.drawText(s,x,y,p);}void center(Canvas c,String s,float x,float y,int z,int col){p.setTypeface(Typeface.create("sans-serif-condensed",1));p.setTextSize(z);p.setColor(col);c.drawText(s,x-p.measureText(s)/2,y,p);}void box(Canvas c,float x,float y,float w,float h,int col,float r){p.setColor(col);c.drawRoundRect(x,y,x+w,y+h,r,r,p);}
 void btn(Canvas c,float x,float y,float w,float h,String s,int id,int col){box(c,x+2,y+4,w,h,0x77000000,12);box(c,x,y,w,h,col,12);p.setStyle(Paint.Style.STROKE);p.setColor(0x88ffffff);c.drawRoundRect(x,y,x+w,y+h,12,12,p);p.setStyle(Paint.Style.FILL);center(c,s,x+w/2,y+h*.64f,Math.min(21,(int)(h*.42f)),Color.WHITE);ui.add(new Hit(x,y,x+w,y+h,id));}
 void bg(Canvas c,int col){c.drawColor(col);p.setShader(new LinearGradient(0,0,W,H,0xff080d20,col,Shader.TileMode.CLAMP));c.drawRect(0,0,W,H,p);p.setShader(null);for(int i=0;i<65;i++){p.setColor(0x33d9f8ff);c.drawCircle((i*137+world*.09f)%(W+20),(i*71)%H,1+i%3,p);}}
 protected void onDraw(Canvas c){W=getWidth();H=getHeight();floor=H*.79f;ui.clear();switch(page){case 0:home(c);break;case 1:levelsPage(c);break;case 2:skins(c);break;case 3:editor(c);break;default:play(c);}postInvalidateDelayed(page==4?16:180);}
 void home(Canvas c){bg(c,0xff172d56);center(c,"GEOMETRY",W/2,H*.25f,Math.min(70,(int)W/10),Color.WHITE);center(c,"DASH",W/2,H*.36f,Math.min(84,(int)W/9),colors[0]);cube(c,W/2-25,H*.44f,50,skin);btn(c,W*.36f,H*.59f,W*.28f,52,"PLAY",1,0xff087fae);btn(c,W*.13f,H*.74f,W*.22f,44,"CUBE SHOP",2,0xff7346a5);btn(c,W*.39f,H*.74f,W*.22f,44,"LEVEL EDITOR",3,0xffad503d);btn(c,W*.65f,H*.74f,W*.22f,44,"ACHIEVEMENTS",5,0xff25856d);text(c,"BEST "+best+"     WINS "+wins,W*.42f,H*.94f,17,0xffc8d8f5);}
 void header(Canvas c,String s){text(c,s,28,42,27,Color.WHITE);btn(c,W-110,14,82,38,"BACK",0,0xff46516b);}
 void levelsPage(Canvas c){bg(c,0xff142544);header(c,"SELECT A LEVEL");for(int i=0;i<4;i++){float x=W*(.07f+i*.23f),y=H*.28f;box(c,x,y,W*.19f,H*.4f,skies[i],15);box(c,x,y,W*.19f,7,colors[i],4);center(c,""+(i+1),x+W*.095f,y+H*.15f,44,Color.WHITE);center(c,levels[i],x+W*.095f,y+H*.26f,Math.min(19,(int)(W*.014f)),Color.WHITE);center(c,new String[]{"EASY","NORMAL","HARD","HARDER"}[i],x+W*.095f,y+H*.33f,14,colors[i]);ui.add(new Hit(x,y,x+W*.19f,y+H*.4f,10+i));}for(int i=0;i<5;i++)btn(c,W*.15f+i*W*.14f,H*.77f,W*.12f,34,new String[]{"CUBE","SHIP","BALL","UFO","WAVE"}[i],30+i,mode==i?0xff008fa8:0xff46516b);}
 void skins(Canvas c){bg(c,0xff17223f);header(c,"CUBE SHOP");String[] names={"CYAN","PINK","GOLD","LIME","VIOLET","ICE","EMBER","MINT"};for(int i=0;i<8;i++){int col=i%4,row=i/4;float x=W*.15f+col*W*.18f,y=H*.25f+row*H*.34f;cube(c,x,y,42,i);center(c,names[i],x+21,y+65,14,Color.WHITE);btn(c,x+55,y+3,110,36,i==skin?"EQUIPPED":"SELECT",50+i,i==skin?0xff237a60:0xff46516b);}}
 void editor(Canvas c){bg(c,0xff12203a);header(c,"LEVEL EDITOR");text(c,"TAP GRID TO BUILD YOUR OWN RUN",26,77,15,0xffb6c8e8);float l=W*.08f,t=H*.18f,cw=W*.84f/20,ch=H*.45f/7;for(int y=0;y<7;y++)for(int x=0;x<20;x++){int i=y*20+x,v=i<custom.size()?custom.get(i):0;p.setColor(0xff3b4c6c);p.setStyle(Paint.Style.STROKE);c.drawRect(l+x*cw,t+y*ch,l+(x+1)*cw,t+(y+1)*ch,p);p.setStyle(Paint.Style.FILL);if(v>0)drawBlock(c,l+x*cw,t+y*ch,cw,ch,v);}btn(c,W*.12f,H*.71f,W*.17f,38,"BLOCK",60,0xff087fae);btn(c,W*.32f,H*.71f,W*.17f,38,"SPIKE",61,0xffb33b62);btn(c,W*.52f,H*.71f,W*.17f,38,"ERASE",62,0xff46516b);btn(c,W*.72f,H*.71f,W*.17f,38,"SAVE",63,0xff25856d);btn(c,W*.39f,H*.83f,W*.22f,38,"TEST LEVEL",64,0xff7346a5);}
 void drawBlock(Canvas c,float x,float y,float w,float h,int v){box(c,x+2,y+2,w-4,h-4,v==1?colors[skin]:v==2?0xffff4d75:0xffffc74a,3);}
 void begin(int l,boolean customLevel){level=l;own=customLevel;page=4;started=dead=won=false;score=0;world=0;py=floor-46;vy=0;last=0;obs.clear();particles.clear();if(!own){Random r=new Random(71+l*33);float x=W+200;for(int i=0;i<42;i++){int type=(i%9==4||i%9==5)?2:1;if(i%13==9)type=3;obs.add(new Obstacle(x,type));x+=150+r.nextInt(95);}}invalidate();}
 void play(Canvas c){bg(c,own?0xff1a1d3c:skies[level]);float now=System.nanoTime()/1e9f;dt=last==0?0:Math.min(.035f,now-last);last=now;if(started&&!dead&&!won)update();drawWorld(c);drawAvatar(c);text(c,own?"CUSTOM LEVEL":levels[level],22,30,17,Color.WHITE);text(c,score+"%",W-90,30,18,Color.WHITE);if(!started&&!dead&&!won)center(c,"TAP TO START",W/2,H*.34f,27,Color.WHITE);if(dead)panel(c,"CRASHED","RETRY",70);if(won)panel(c,"LEVEL COMPLETE!","NEXT",71);}
 void update(){world+=(360+level*30)*dt;score=Math.min(100,(int)(world/5100*100));if(score>best){best=score;prefs.edit().putInt("best",best).apply();}float base=floor-46;if(mode==0||mode==2||mode==3){vy+=1900*dt;py+=vy*dt;if(py>base){py=base;vy=0;}}else if(mode==1){vy+=(holding?-1250:1350)*dt;py=Math.max(24,Math.min(base,py+vy*dt));}else py=Math.max(24,Math.min(base,py+(holding?-580:580)*dt));for(Obstacle o:obs){float x=o.x-world;if(x<-100||x>W+100)continue;float top=o.type==1?floor-44:o.type==2?floor-118:floor-155;float hh=o.type==1?44:o.type==2?14:115;if(x<px+36&&x+48>px&&py+40>top&&py<top+hh){crash();break;}if(!o.passed&&x<px){o.passed=true;burst(px,py,colors[skin],8);}}trail+=dt;if(trail>.035f){trail=0;particles.add(new Particle(px+8,py+20,colors[skin]));}for(int i=particles.size()-1;i>=0;i--){Particle q=particles.get(i);q.x-=70*dt;q.life-=dt;if(q.life<=0)particles.remove(i);}if(world>5100){won=true;started=false;wins++;prefs.edit().putInt("wins",wins).apply();stopMusic();}}
 void crash(){dead=true;started=false;stopMusic();burst(px+20,py+20,0xffff547f,28);}void burst(float x,float y,int col,int n){for(int i=0;i<n;i++)particles.add(new Particle(x,y,col));}
 void drawWorld(Canvas c){float par=world*.24f;for(int i=0;i<9;i++){float x=(i*180-par)%(W+200)-80;box(c,x,H*.24f+i%3*34,80,5,0x223ceaff,3);}box(c,0,floor,W,H-floor,0xff11182c,0);box(c,0,floor,W,7,colors[(level+skin)%8],0);for(int i=0;i<W/54+2;i++){float x=i*54-world%54;box(c,x,floor+8,51,H-floor-8,0xff26324c,1);box(c,x+5,floor+17,8,5,0xff53627e,1);}if(own){for(int i=0;i<custom.size();i++){int v=custom.get(i);if(v>0){float x=W*.08f+i%20*(W*.84f/20)-world%W,y=floor-(i/20+1)*35;if(v==2){p.setColor(0xffff5274);Path t=new Path();t.moveTo(x,y+35);t.lineTo(x+15,y);t.lineTo(x+30,y+35);t.close();c.drawPath(t,p);}else box(c,x,y,30,30,colors[skin],2);}}}else for(Obstacle o:obs){float x=o.x-world;if(x<-100||x>W+100)continue;if(o.type==1){p.setColor(0xffe9edf9);Path t=new Path();t.moveTo(x,floor);t.lineTo(x+22,floor-44);t.lineTo(x+44,floor);t.close();c.drawPath(t,p);}else if(o.type==2){box(c,x,floor-118,48,14,0xff8c849d,2);box(c,x+5,floor-114,38,5,0xffd4cce2,1);}else{p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(7);p.setColor(0xffd44cff);c.drawOval(x,floor-155,x+30,floor-40,p);p.setStyle(Paint.Style.FILL);}}for(Particle q:particles){p.setColor(q.color);p.setAlpha((int)(255*Math.max(0,q.life/.7f)));c.drawCircle(q.x,q.y,Math.max(1,q.life*5),p);}p.setAlpha(255);}
 void cube(Canvas c,float x,float y,float s,int k){c.save();c.rotate(-12,x+s/2,y+s/2);box(c,x,y,s,s,colors[k],7);box(c,x+6,y+8,s*.28f,s*.27f,0xff17243d,3);box(c,x+s*.62f,y+8,s*.28f,s*.27f,0xff17243d,3);box(c,x+8,y+s*.65f,s-16,5,0xff17243d,2);c.restore();}
 void drawAvatar(Canvas c){if(mode==0||mode==2)cube(c,px,py,42,skin);else if(mode==1){p.setColor(colors[skin]);Path t=new Path();t.moveTo(px-5,py+8);t.lineTo(px+45,py+21);t.lineTo(px-5,py+36);t.lineTo(px+7,py+21);t.close();c.drawPath(t,p);p.setColor(0xffffad45);c.drawCircle(px+5,py+21,5,p);}else if(mode==3){p.setColor(colors[skin]);c.drawOval(px,py+5,px+44,py+38,p);p.setColor(Color.WHITE);c.drawCircle(px+15,py+18,4,p);c.drawCircle(px+29,py+18,4,p);}else{p.setColor(colors[skin]);Path t=new Path();t.moveTo(px+21,py);t.lineTo(px+42,py+21);t.lineTo(px+21,py+42);t.lineTo(px,py+21);t.close();c.drawPath(t,p);}}
 void panel(Canvas c,String title,String action,int id){box(c,W*.30f,H*.29f,W*.40f,H*.48f,0xee10182d,18);center(c,title,W/2,H*.43f,32,Color.WHITE);btn(c,W*.38f,H*.53f,W*.24f,44,action,id,0xff087fae);btn(c,W*.38f,H*.65f,W*.24f,38,"MENU",0,0xff46516b);}
 void act(int id){if(id==0){stopMusic();page=0;}else if(id==1)page=1;else if(id==2)page=2;else if(id==3)page=3;else if(id==5)page=0;else if(id>=10&&id<14)begin(id-10,false);else if(id>=30&&id<35)mode=id-30;else if(id>=50&&id<58){skin=id-50;prefs.edit().putInt("skin",skin).apply();}else if(id>=60&&id<=62)tool=id-59;else if(id==63){StringBuilder s=new StringBuilder();for(int v:custom){if(s.length()>0)s.append(',');s.append(v);}prefs.edit().putString("map",s.toString()).apply();}else if(id==64)begin(0,true);else if(id==70)begin(level,own);else if(id==71)begin((level+1)%4,false);invalidate();}
 public boolean onTouchEvent(MotionEvent e){float x=e.getX(),y=e.getY();if(page==4){if(e.getAction()==0){if(dead||won){for(Hit h:ui)if(h.hit(x,y)){act(h.id);return true;}}else{holding=true;if(!started){started=true;last=0;music();}if(mode==0&&py>=floor-47)vy=-710;else if(mode==2)vy=py>floor/2?-700:700;else if(mode==3)vy=-600;}return true;}if(e.getAction()==1){holding=false;return true;}return true;}if(e.getAction()==0){if(page==3){float l=W*.08f,t=H*.18f,cw=W*.84f/20,ch=H*.45f/7;if(x>=l&&x<l+cw*20&&y>=t&&y<t+ch*7){int i=(int)((y-t)/ch)*20+(int)((x-l)/cw);while(custom.size()<140)custom.add(0);custom.set(i,tool);invalidate();return true;}}for(int i=ui.size()-1;i>=0;i--)if(ui.get(i).hit(x,y)){act(ui.get(i).id);return true;}}return true;}
 class Obstacle{float x;int type;boolean passed;Obstacle(float a,int t){x=a;type=t;}}class Particle{float x,y,life;int color;Particle(float a,float b,int c){x=a;y=b;color=c;life=.45f+rng.nextFloat()*.35f;}}class Hit{float l,t,r,b;int id;Hit(float a,float z,float q,float d,int i){l=a;t=z;r=q;b=d;id=i;}boolean hit(float x,float y){return x>=l&&x<=r&&y>=t&&y<=b;}}
 }
}